user:
{
 "batch": "episode-001.txt#S01",
 "lines": [
  {
   "line_id": "E01-L001",
   "speaker": "Edda Halloran",
   "english": "The lamp stays lit.",
   "telugu": "దీపం వెలిగేలా ఉంది."
  },
  {
   "line_id": "E01-L003",
   "speaker": "Edda Halloran",
   "english": "I set it down an hour ago.",
   "telugu": "నేను దాన్ని ఒక గంటకు ముందు పెట్టాను."
  },
  {
   "line_id": "E01-L004",
   "speaker": "Halloran (Edda's father)",
   "english": "Caine came again while you slept.",
   "telugu": "ఎడ్డా, కెయిన్ మళ్లీ నీవు నిద్రిస్తున్నప్పుడు వచ్చాడు."
  },
  {
   "line_id": "E01-L005",
   "speaker": "Edda Halloran",
   "english": "She always comes when I sleep.",
   "telugu": "ఆమె నేను నిద్రిస్తున్నప్పుడు ఎప్పుడూ వస్తుంది."
  },
  {
   "line_id": "E01-L006",
   "speaker": "Halloran (Edda's father)",
   "english": "Promise me you will not sign her paper.",
   "telugu": "వాగ్దానం చేయి, నీవు ఆమె పత్రాన్ని సంతకం చేయవద్దు."
  },
  {
   "line_id": "E01-L007",
   "speaker": "Edda Halloran",
   "english": "What paper?",
   "telugu": "ఏ పత్రం?"
  }
 ]
}

{
 "batch": "episode-001.txt#S02",
 "lines": [
  {
   "line_id": "E01-L014",
   "speaker": "Mistress Caine",
   "english": "The debt is mine, the deed is mine, the winter is mine.",
   "telugu": "బాకీ నా, ఒప్పందం నా, శీతాకాలం నా."
  },
  {
   "line_id": "E01-L015",
   "speaker": "Edda Halloran",
   "english": "Say it once more.",
   "telugu": "దయచేసి, మళ్ళీ ఒకసారి చెప్పండి."
  },
  {
   "line_id": "E01-L017",
   "speaker": "Joss Marek",
   "english": "Tell that to the tide, Mistress.",
   "telugu": "ఆ మాటను జలానికి చెప్పండి, Mistress."
  },
  {
   "line_id": "E01-L021",
   "speaker": "Edda Halloran",
   "english": "By your authority. Yes.",
   "telugu": "మీ అధికారంతో. అవును."
  }
 ]
}

{
 "batch": "episode-001.txt#S03",
 "lines": [
  {
   "line_id": "E01-L023",
   "speaker": "Edda Halloran",
   "english": "No.",
   "telugu": "లేదు."
  },
  {
   "line_id": "E01-L024",
   "speaker": "Silas Vane",
   "english": "She always says no ...",
   "telugu": "మిస్ హాలొరన్, ఆమె ఎప్పుడూ 'లేదు' అంటుంది..."
  },
  {
   "line_id": "E01-L025",
   "speaker": "Silas Vane",
   "english": "... until the price is right.",
   "telugu": "... ధర సరైనంత వరకు."
  },
  {
   "line_id": "E01-L026",
   "speaker": "Halloran (Edda's father)",
   "english": "Edda, my girl, do not ...",
   "telugu": "ఎడ్డా, నా అమ్మాయా, చేయవద్దు..."
  },
  {
   "line_id": "E01-L027",
   "speaker": "Halloran (Edda's father)",
   "english": "... sign nothing tonight.",
   "telugu": "... ఈ రాత్రి ఏదీ సంతకం చేయకు."
  },
  {
   "line_id": "E01-L029",
   "speaker": "Mistress Caine",
   "english": "Aunt. That is what you called me at Christmastide.",
   "telugu": "అంటీ. మీరు క్రిస్మస్ కాలంలో నన్ను అంతే పిలిచారు."
  },
  {
   "line_id": "E01-L030",
   "speaker": "Edda Halloran",
   "english": "Call it what you like.",
   "telugu": "మీకు నచ్చినట్లుగా పిలవండి."
  }
 ]
}

{
 "batch": "episode-002.txt#S01",
 "lines": [
  {
   "line_id": "E02-L004",
   "speaker": "Joss Marek",
   "english": "Ticket burnt with the ship.",
   "telugu": "టికెట్ నౌకతో కాలిపోయింది."
  },
  {
   "line_id": "E02-L006",
   "speaker": "Edda Halloran",
   "english": "So it is you filling his head.",
   "telugu": "అలా అయితే, మీరు, Marek, అతని తల నింపుతున్నారా?"
  },
  {
   "line_id": "E02-L007",
   "speaker": "Joss Marek",
   "english": "His head was full already.",
   "telugu": "అతని తల ఇప్పటికే నిండిపోయింది."
  },
  {
   "line_id": "E02-L009",
   "speaker": "Company clerk (Caine's man, grey coat)",
   "english": "Mistress Caine will hear of this.",
   "telugu": "Mistress Caine దీనిని వినిపిస్తారు."
  }
 ]
}

{
 "batch": "episode-002.txt#S02",
 "lines": [
  {
   "line_id": "E02-L010",
   "speaker": "Delia",
   "english": "Eat, love. He will want you standing.",
   "telugu": "తిను, ప్రియ. అతను నిన్ను నిలబడి ఉండాలని కోరుతాడు."
  },
  {
   "line_id": "E02-L011",
   "speaker": "Edda Halloran",
   "english": "He wants the lamp.",
   "telugu": "అతను దీపాన్ని కోరుకుంటున్నారు."
  },
  {
   "line_id": "E02-L012",
   "speaker": "Delia",
   "english": "He wants your father off the rock before the spring.",
   "telugu": "అతను నీ తండ్రిని వసంతానికి ముందు రాయిపై నుంచి తొలగించాలని కోరుకుంటున్నాడు."
  },
  {
   "line_id": "E02-L013",
   "speaker": "Edda Halloran",
   "english": "That is the same thing.",
   "telugu": "అది అదే విషయం."
  },
  {
   "line_id": "E02-L015",
   "speaker": "Brother Anselm",
   "english": "Miss Halloran. The company offers charity for the keeper's winter.",
   "telugu": "మిస్ హల్లొరాన్, కంపెనీ కీపర్ శీతాకాలానికి దానం అందిస్తోంది."
  },
  {
   "line_id": "E02-L016",
   "speaker": "Edda Halloran",
   "english": "Charity from Caine.",
   "telugu": "కేన్ నుండి దానం."
  },
  {
   "line_id": "E02-L020",
   "speaker": "Edda Halloran",
   "english": "Father does not sign. That is the answer.",
   "telugu": "తండ్రి సంతకం చేయడు. అది సమాధానం."
  }
 ]
}

{
 "batch": "episode-002.txt#S03",
 "lines": [
  {
   "line_id": "E02-L025",
   "speaker": "Edda Halloran",
   "english": "... how did you ...",
   "telugu": "... మీరు ఎలా ..."
  },
  {
   "line_id": "E02-L026",
   "speaker": "Joss Marek",
   "english": "Your father taught me to read a gate in '61.",
   "telugu": "Mee thandri naaku 61 lo darwaza chadavadam nerpindi."
  },
  {
   "line_id": "E02-L028",
   "speaker": "Edda Halloran",
   "english": "Hush now, Father. I am here.",
   "telugu": "Shanthamga undi, Nanna. Nenu ikkada unna."
  },
  {
   "line_id": "E02-L029",
   "speaker": "Joss Marek",
   "english": "She has no idea what a signature costs.",
   "telugu": "Aame ki hastakshara ki emi teliyadu."
  },
  {
   "line_id": "E02-L030",
   "speaker": "Edda Halloran",
   "english": "He called me 'she' like I was a clause in the paper.",
   "telugu": "Adi nannu 'aame' ani pilichadu, nenu patrikalo oka vakyam laga."
  },
  {
   "line_id": "E02-L031",
   "speaker": "Joss Marek",
   "english": "Lock the gate, Edda. It is you he means.",
   "telugu": "Darwaza nilipi, Edda. Aadani artham meeru."
  }
 ]
}

{
 "batch": "episode-003.txt#S01",
 "lines": [
  {
   "line_id": "E03-L002",
   "speaker": "Edda Halloran",
   "english": "I have an hour, Mistress Caine.",
   "telugu": "Naaku oka gaṇṭa undi, Mistress Caine."
  },
  {
   "line_id": "E03-L003",
   "speaker": "Mistress Caine",
   "english": "You have the tide. It is less.",
   "telugu": "Mee daggara aapada undi. Adi takkuva."
  },
  {
   "line_id": "E03-L006",
   "speaker": "Mistress Caine",
   "english": "Carry it. I will watch.",
   "telugu": "Adi teesukondi. Nenu choostanu."
  },
  {
   "line_id": "E03-L008",
   "speaker": "Edda Halloran",
   "english": "He bought them.",
   "telugu": "Avaadu vatini konnaadu."
  },
  {
   "line_id": "E03-L010",
   "speaker": "Edda Halloran",
   "english": "What do you want, Silas, out of a dead man's paper?",
   "telugu": "Silas Vane, mruthyu vyakti patra nundi meeru emi korukuntunnaru?"
  },
  {
   "line_id": "E03-L011",
   "speaker": "Silas Vane",
   "english": "Your name in my bed and my seal on that lamp.",
   "telugu": "Miss Halloran, mee peru naa bed lo undi, alage aa lamp meeda naa seal."
  },
  {
   "line_id": "E03-L012",
   "speaker": "Mistress Caine",
   "english": "You are not worth a seal. Take her away.",
   "telugu": "Meeru seal ki kooda layakaledu. Aameyi teesukondi."
  }
 ]
}

{
 "batch": "episode-003.txt#S02",
 "lines": [
  {
   "line_id": "E03-L014",
   "speaker": "Joss Marek",
   "english": "Someone did. From the stair.",
   "telugu": "ఎవరో చేశారు. మెట్ల నుండి."
  },
  {
   "line_id": "E03-L017",
   "speaker": "Joss Marek",
   "english": "Your light is my work.",
   "telugu": "నీ వెలుగు నా పని."
  },
  {
   "line_id": "E03-L018",
   "speaker": "Edda Halloran",
   "english": "Then tell me what a '61 inquiry letter costs a keeper's daughter.",
   "telugu": "మారెక్, ‘61 విచారణ లేఖ ఒక కీపర్ కుమార్తెకు ఎంత ఖర్చవుతుందో చెప్పండి."
  },
  {
   "line_id": "E03-L021",
   "speaker": "Edda Halloran",
   "english": "Not tonight.",
   "telugu": "ఈ రాత్రి కాదు."
  },
  {
   "line_id": "E03-L023",
   "speaker": "Joss Marek",
   "english": "She does not know she is being priced and not courted.",
   "telugu": "ఆమెకి తెలియదు, ఆమెను ధరలతో చూస్తున్నారు, ప్రేమతో కాదు."
  },
  {
   "line_id": "E03-L024",
   "speaker": "Edda Halloran",
   "english": "Aunt would have said that nicer.",
   "telugu": "అంటీ, అది మరింత బాగుగా చెప్పేవారు."
  }
 ]
}

{
 "batch": "episode-003.txt#S03",
 "lines": [
  {
   "line_id": "E03-L025",
   "speaker": "Halloran (Edda's father)",
   "english": "You went to the house. My girl, why did you go?",
   "telugu": "నీవు ఇంటికి వెళ్లావు, నా అమ్మాయి. ఎందుకు వెళ్లావు?"
  },
  {
   "line_id": "E03-L029",
   "speaker": "Edda Halloran",
   "english": "I will not let them take it.",
   "telugu": "నేను వాళ్లు దాన్ని తీసుకెళ్లనివ్వను."
  },
  {
   "line_id": "E03-L030",
   "speaker": "Halloran (Edda's father)",
   "english": "Say it as a promise, not a ...",
   "telugu": "దాన్ని వాగ్దానంగా చెప్పు, సవాల్‌గా కాదు—"
  },
  {
   "line_id": "E03-L031",
   "speaker": "Edda Halloran",
   "english": "... a dare. I hear you, Father.",
   "telugu": "నేను వినుతున్నాను, నాన్నా."
  }
 ]
}

{
 "batch": "episode-004.txt#S01",
 "lines": [
  {
   "line_id": "E04-L001",
   "speaker": "Edda Halloran",
   "english": "Keep it turning. Keep it turning.",
   "telugu": "తిరుగుతూ ఉండు. తిరుగుతూ ఉండు."
  },
  {
   "line_id": "E04-L002",
   "speaker": "Voice of the lamp",
   "english": "One, two, three, four —",
   "telugu": "ఒకటి, రెండు, మూడు, నాలుగు —"
  },
  {
   "line_id": "E04-L004",
   "speaker": "Joss Marek",
   "english": "LIGHT THE STAIR! Somebody light the stair!",
   "telugu": "సీడీని వెలిగించండి! ఎవరో సీడీని వెలిగించండి!"
  },
  {
   "line_id": "E04-L006",
   "speaker": "Joss Marek",
   "english": "Then he'll be wet and right, in that order.",
   "telugu": "అప్పుడు అతను తడిగా, సరైనవాడిగా ఉంటుంది, ఆ క్రమంలో."
  },
  {
   "line_id": "E04-L007",
   "speaker": "Edda Halloran",
   "english": "Turn to him. Turn to him, he is my father's water.",
   "telugu": "తిరుగు అతనికి. తిరుగు అతనికి, అతను నా తండ్రి నీరు."
  }
 ]
}

{
 "batch": "episode-004.txt#S02",
 "lines": [
  {
   "line_id": "E04-L009",
   "speaker": "Edda Halloran",
   "english": "Nobody's. The bar held.",
   "telugu": "ఎవరికి కూడా కాదు. బార్ నిలిచింది."
  },
  {
   "line_id": "E04-L011",
   "speaker": "Joss Marek",
   "english": "Your bar held. The trawler did not.",
   "telugu": "నీ బార్ నిలిచింది. ట్రాలర్ కాదు."
  },
  {
   "line_id": "E04-L013",
   "speaker": "Joss Marek",
   "english": "Two alive, three gone, and the boy's still on my deck.",
   "telugu": "రెండు జీవించి, మూడు వెళ్లిపోయారు, బాలుడు ఇంకా నా డెక్క్‌పై ఉన్నాడు."
  },
  {
   "line_id": "E04-L014",
   "speaker": "Halloran (Edda's father)",
   "english": "Three on my shoal. Say it to me.",
   "telugu": "ఎడ్డా, నా షోల్‌లో మూడు. నాకె చెప్పు."
  },
  {
   "line_id": "E04-L015",
   "speaker": "Joss Marek",
   "english": "I'll say it any way you need.",
   "telugu": "నీకు అవసరమైన విధంగా నేను చెప్పుతాను."
  },
  {
   "line_id": "E04-L017",
   "speaker": "Joss Marek",
   "english": "He's the one who can't sleep after.",
   "telugu": "అతను తర్వాత నిద్రపోని వాడు."
  },
  {
   "line_id": "E04-L018",
   "speaker": "Edda Halloran",
   "english": "Joss — the coat. Whose?",
   "telugu": "జోస్ — కోట్. ఎవరి?"
  }
 ]
}

{
 "batch": "episode-004.txt#S03",
 "lines": [
  {
   "line_id": "E04-L021",
   "speaker": "Edda Halloran",
   "english": "It isn't alone.",
   "telugu": "ఇది ఒంటరిగా లేదు."
  },
  {
   "line_id": "E04-L023",
   "speaker": "Edda Halloran",
   "english": "My father put me up here at nine and said count and don't stop.",
   "telugu": "నా తండ్రి నన్ను తొమ్మిదేళ్ల వయస్సులో ఇక్కడ పెట్టి, లెక్కించు, ఆపకు అని చెప్పారు."
  },
  {
   "line_id": "E04-L024",
   "speaker": "Voice of the lamp",
   "english": "— nine, ten, eleven, twelve —",
   "telugu": "— తొమ్మిది, పది, పదకొండు, పన్నెండు —"
  },
  {
   "line_id": "E04-L025",
   "speaker": "Edda Halloran",
   "english": "That's enough. Go down.",
   "telugu": "ఇది సరిపోతుంది. దిగు."
  },
  {
   "line_id": "E04-L027",
   "speaker": "Edda Halloran",
   "english": "If you touch my father's lamp you'll be standing in it, not beside it.",
   "telugu": "నీవు నా తండ్రి దీపాన్ని తాకితే, దాని పక్కన కాదు, దానిలోనే నిలబెడతావు."
  }
 ]
}

{
 "batch": "episode-005.txt#S01",
 "lines": [
  {
   "line_id": "E05-L003",
   "speaker": "Company clerk (shipping office, grey beard)",
   "english": "That one was written off before it sank.",
   "telugu": "ఆది మునిగే ముందు వదిలివేయబడింది."
  },
  {
   "line_id": "E05-L007",
   "speaker": "Edda Halloran",
   "english": "Father Anselm. Is this your ledger too?",
   "telugu": "ఫాదర్ యాన్సెల్మ్ గారు. ఇది మీ లెడ్జర్ కూడా?"
  },
  {
   "line_id": "E05-L009",
   "speaker": "Edda Halloran",
   "english": "And Caine gives.",
   "telugu": "మరియు మిస్ట్రెస్ కేన్ గారు ఇస్తారు."
  },
  {
   "line_id": "E05-L010",
   "speaker": "Brother Anselm",
